#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

typedef struct {
    long long a, b;
} Effect;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

int cmp_meals(const void *p1, const void *p2) {
    const Effect *m1 = (const Effect *)p1;
    const Effect *m2 = (const Effect *)p2;
    __int128 v1 = (__int128)m1->b * (m2->a - 1);
    __int128 v2 = (__int128)m2->b * (m1->a - 1);
    if (v1 > v2) return -1;
    if (v1 < v2) return 1;
    return 0;
}

int cmp_spells(const void *p1, const void *p2) {
    const Effect *s1 = (const Effect *)p1;
    const Effect *s2 = (const Effect *)p2;
    if (s1->a != s2->a) {
        return (s1->a < s2->a) ? -1 : 1;
    }
    if (s1->b != s2->b) {
        return (s1->b > s2->b) ? -1 : 1;
    }
    return 0;
}

int get_best(long long x, const long long *T, int h) {
    int low = 0, high = h - 2, ans = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (x >= T[mid]) {
            ans = mid + 1;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

int main(void) {
    int n, m;
    long long k;
    if (scanf("%d %d %lld", &n, &m, &k) != 3) return 0;

    Effect *spells = (Effect *)malloc(n * sizeof(Effect));
    for (int i = 0; i < n; i++) {
        scanf("%lld", &spells[i].a);
    }
    for (int i = 0; i < n; i++) {
        scanf("%lld", &spells[i].b);
    }

    Effect *meals = (Effect *)malloc(m * sizeof(Effect));
    for (int i = 0; i < m; i++) {
        scanf("%lld", &meals[i].a);
    }
    for (int i = 0; i < m; i++) {
        scanf("%lld", &meals[i].b);
    }

    qsort(meals, m, sizeof(Effect), cmp_meals);

    long long A_meals = 1, B_meals = 0;
    for (int i = 0; i < m; i++) {
        long long a = meals[i].a % MOD;
        long long b = meals[i].b % MOD;
        A_meals = (A_meals * a) % MOD;
        B_meals = (B_meals * a + b) % MOD;
    }
    free(meals);

    qsort(spells, n, sizeof(Effect), cmp_spells);

    int u = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || spells[i].a != spells[i - 1].a) {
            spells[u++] = spells[i];
        }
    }

    Effect *H = (Effect *)malloc(u * sizeof(Effect));
    int h = 0;
    for (int i = 0; i < u; i++) {
        while (h > 0 && spells[i].b >= H[h - 1].b) {
            h--;
        }
        while (h >= 2) {
            __int128 b1_b2 = H[h - 2].b - H[h - 1].b;
            __int128 a2_a1 = H[h - 1].a - H[h - 2].a;
            __int128 b2_b3 = H[h - 1].b - spells[i].b;
            __int128 a3_a2 = spells[i].a - H[h - 1].a;
            if (b2_b3 * a2_a1 <= b1_b2 * a3_a2) {
                h--;
            } else {
                break;
            }
        }
        H[h++] = spells[i];
    }
    free(spells);

    long long *T = (long long *)malloc((h > 1 ? h - 1 : 1) * sizeof(long long));
    for (int i = 0; i < h - 1; i++) {
        long long num = H[i].b - H[i + 1].b;
        long long den = H[i + 1].a - H[i].a;
        T[i] = (num + den - 1) / den;
    }

    int q;
    if (scanf("%d", &q) != 1) return 0;

    for (int qi = 0; qi < q; qi++) {
        long long x;
        scanf("%lld", &x);

        long long cur_x = x;
        long long rem_k = k;

        while (rem_k > 0) {
            int idx = get_best(cur_x, T, h);
            if (idx == h - 1) {
                break;
            }
            cur_x = H[idx].a * cur_x + H[idx].b;
            rem_k--;
        }

        if (rem_k > 0) {
            long long A = H[h - 1].a % MOD;
            long long B = H[h - 1].b % MOD;
            cur_x %= MOD;

            if (H[h - 1].a == 1) {
                cur_x = (cur_x + (rem_k % MOD) * B) % MOD;
            } else {
                long long pA = power(A, rem_k);
                long long inv = modInverse((A - 1 + MOD) % MOD);
                long long geom = ((pA - 1 + MOD) % MOD * inv) % MOD;
                cur_x = (pA * cur_x + B * geom) % MOD;
            }
        } else {
            cur_x %= MOD;
        }

        long long ans = (A_meals * cur_x + B_meals) % MOD;
        printf("%lld\n", ans);
    }

    free(H);
    free(T);

    return 0;
}
